def cAPS_lOCK(string):
    if len(string) == 1 :
        return string.swapcase()
    if string[0 + 1] != string[1]:
        return string.lower()
    elif string[1:].isupper():
        return string.swapcase()
    elif string.isupper():
        return string.capitalize()
    else :
        return string

