def change(b):
    if "a" <= b <= "z":
        return chr(ord(b) - ord('a') + ord('A'))
    else:
        return chr(ord(b) - ord('A') + ord('a'))
a = input()
A1 = {chr(i):0 for i in range(ord("a"), ord("z") + 1)}
A2 = {chr(i):0 for i in range(ord("A"), ord("Z") + 1)}
if len(a) == 1:
    if "a" <= a[0] <= "z":
        print(chr(ord(a[0]) - ord('a') + ord('A')))
    else:
        print(chr(ord(a[0]) + ord('a') - ord('A')))
else:
    check = 1
    for i in range(1 , len(a)):
        if ord(a[i]) < 65 or ord(a[i]) > 90:
            check = 0
            break
    if check == 1:
        for j in range(len(a)):
            if ord(a[j]) >= 97:
                print(chr(ord(a[j]) - 32) , end = "")
            else:
                print(chr(ord(a[j]) + 32) , end = "")
    if check == 0:
        print(a)

def solve(s):
    if len(s) == 1 or s[1:].isupper():
        return s.swapcase()
    return s

